function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  if (!user || !sheet) return null;
  const download = async () => {
    const [info, people, claims, rates, settings] = await Promise.all([
      readFresh<SheetInfo>(queryClient, sheetQueryKey(sheet), sheetInfoPath(sheet)),
      readFresh<Person[]>(queryClient, peopleQueryKey(sheet), peoplePath(sheet)),
      readFresh<Claim[]>(queryClient, claimsQueryKey(sheet), claimsPath(sheet)),
      readFresh<Rate[]>(queryClient, ratesQueryKey(sheet), ratesPath(sheet)),
      readFresh<Settings>(queryClient, settingsQueryKey(sheet), settingsPath(sheet)),
    ]);
    const today = info.today;
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      lines.push([p.name, gradeOn(p, today), p.retiredFrom ?? '', personDue(p, claims, rates, today, settings, people)]);
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));

const treePath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/tree`;

/** The lines for one sheet's matching people, in list order. */
async function linesOf(sheetId: string, text: string): Promise<string[]> {
  const [info, people, claims, rates, settings] = await Promise.all([
    getJsonLive<SheetInfo>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    getJsonLive<Person[]>(peoplePath(sheetId)),
    getJsonLive<Claim[]>(claimsPath(sheetId)),
    getJsonLive<Rate[]>(ratesPath(sheetId)),
    getJsonLive<Settings>(settingsPath(sheetId)),
  ]);
  const key = text.toLowerCase();
  return people
    .filter((p) => [p.name, ...p.aliases].some((n) => n.toLowerCase().includes(key)))
    .map((p) => `${sheetId} ${shownName(p, info.today)} ${personDue(p, claims, rates, info.today, settings, people)}`);
}

async function searchTree(sheetId: string, text: string): Promise<string[]> {
}

async function compareSnapshots(sheetId: string, from: string, to: string): Promise<string[]> {
  const [info, people, claims, rates, settings] = await Promise.all([
    getJsonLive<SheetInfo>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    getJsonLive<Person[]>(peoplePath(sheetId)),
    getJsonLive<Claim[]>(claimsPath(sheetId)),
    getJsonLive<Rate[]>(ratesPath(sheetId)),
    getJsonLive<Settings>(settingsPath(sheetId)),
  ]);
  const fromDate = from.trim() === '' ? info.today : from.trim();
  return people.map((p) => {
    const then = snapshotOn(p, fromDate);
    const now = to.trim() === '' ? personDue(p, claims, rates, info.today, settings, people) : snapshotOn(p, to.trim());
    return [p.name, then, now].filter((s) => s !== '').join(' ');
  });
  grades: Record<string, string>;
  statuses: Record<string, number>;
};

/** A sheet's figures, from its people, claims, rates, today and settings. */
export function figuresFrom(people: Person[], claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): Figures {
  const current = people.filter((p) => p.retiredFrom === null);
  return {
    people: people.map((p) => [p.name, ...(p.aliases ?? [])].map(nameKey)),
    dues: people.map((p) => personDue(p, claims, rates, today, settings, people)),
    overdues: people.map((p) => overdueOf(p, claims, rates, today, settings).total),
    overdueCount: people.reduce((n, p) => n + overdueOf(p, claims, rates, today, settings).count, 0),
    grades: Object.fromEntries(GRADES.map((g) => [g, sumDue(current.filter((p) => gradeOn(p, today) === g)
      .map((p) => personDue(p, claims, rates, today, settings, people)))])),
    statuses: Object.fromEntries(STATUSES.map((s) => [s, claims.filter((c) => c.status === s).length])),
  };
}

}

const sheetPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;
const childrenPath = (sheetId: string) => `${sheetPath(sheetId)}/children`;

export const descendantsQueryKey = (sheetId: string) => ['sheet', sheetId, 'descendants'] as const;

/** A sheet's figures, read from the store as the screen shows it (as of its date, if any). */
export async function figuresOf(id: string): Promise<Figures> {
  const [info, people, claims, rates, settings] = await Promise.all([
    getJson<SheetInfo>(sheetPath(id)),
    getJson<Person[]>(peoplePath(id)),
    getJson<Claim[]>(claimsPath(id)),
    getJson<Rate[]>(ratesPath(id)),
    getJson<Settings>(settingsPath(id)),
  ]);
  return figuresFrom(people, claims, rates, info.today, settings);
}

/** Each descendant sheet's figures, read from the store as the screen shows it (a sheet reached twice counts once). */
export async function descendantFigures(sheetId: string): Promise<Figures[]> {
  const seen = new Set([sheetId]);
  const ids: string[] = [];
  for (let level = [sheetId]; level.length > 0; ) {
    const children = (await Promise.all(level.map((id) => getJsonLive<string[]>(childrenPath(id))))).flat();
    level = children.filter((id) => !seen.has(id) && (seen.add(id), true));
    ids.push(...level);
  }
  return Promise.all(ids.map(figuresOf));
}

function ConsolidatedFigures() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const settings = useSettings();
  const today = useSheetToday();
  const asOf = currentAsOf();
  const descendants = useQuery({
    queryKey: [...descendantsQueryKey(sheet ?? ''), asOf],
    queryFn: () => descendantFigures(sheet ?? ''),
    enabled: !!sheet,
  });
  if (!user || !sheet) return null;

